import java.util.*;import java.util.zip.*;import java.nio.file.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
public class Inspect implements Opcodes{
 static int checks;static void ok(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
 static ClassNode read(ZipFile z,String n)throws Exception{ClassNode c=new ClassNode();new ClassReader(z.getInputStream(z.getEntry(n+".class")).readAllBytes()).accept(c,0);return c;}
 public static void main(String[]args)throws Exception{try(ZipFile z=new ZipFile(args[0])){for(String name:List.of("NeedsClientEvents","NeedsClientModEvents")){ClassNode c=read(z,"dev/zomboid/decor/needs/"+name);AnnotationNode a=c.visibleAnnotations.getFirst();int index=a.values.indexOf("value");Object value=((List<?>)a.values.get(index+1)).getFirst();ok(value instanceof String[] e&&e[0].equals("Lnet/neoforged/api/distmarker/Dist;")&&e[1].equals("CLIENT"),"client subscriber must contain enum array, not string array");}
 ClassNode mod=read(z,"net/mcreator/doomsdaydecoration/DoomsdayDecorationMod");boolean wc=false;for(MethodNode m:mod.methods)for(AbstractInsnNode i:m.instructions)if(i instanceof LdcInsnNode l&&l.cst.equals("wc")){wc=i.getNext()instanceof MethodInsnNode call&&call.owner.equals("java/util/Set")&&call.desc.equals("(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)Ljava/util/Set;");}ok(wc,"WC goes through existing raised-placement item factory");
 ClassNode item=read(z,"net/mcreator/doomsdaydecoration/item/VendingMachineBlockItem");MethodNode method=item.methods.stream().filter(m->m.name.equals("controllerPosition")).findFirst().orElseThrow();ok(method.instructions.iterator().hasNext(),"native placement offset preserved");boolean above=false;for(AbstractInsnNode i:method.instructions)if(i instanceof MethodInsnNode call&&call.name.equals("above")&&call.desc.equals("(I)Lnet/minecraft/core/BlockPos;"))above=true;ok(above,"native item places controller above ordinary target");
 ClassNode block=read(z,"net/mcreator/doomsdaydecoration/port/PortedBlock");MethodNode use=block.methods.stream().filter(m->m.name.equals("useWithoutItem")).findFirst().orElseThrow();List<String> calls=new ArrayList<>();for(AbstractInsnNode i:use.instructions)if(i instanceof MethodInsnNode call)calls.add(call.owner+"."+call.name);ok(calls.indexOf("dev/zomboid/decor/needs/Toilets.use")<calls.indexOf("dev/zomboid/decor/Beds.use"),"toilets handled before existing bed and sound use");ok(block.methods.stream().filter(m->m.name.equals("entityInside")).count()==1,"single native wire contact hook");
 for(String name:List.of("NeedsEvents","NeedsModEvents")){ClassNode c=read(z,"dev/zomboid/decor/needs/"+name);for(MethodNode m:c.methods)for(AbstractInsnNode i:m.instructions)if(i instanceof MethodInsnNode call)ok(!call.owner.contains("/client/"),"dedicated server handlers must not load client code");}
 }
 System.out.println("NATIVE_HOOK_AND_SIDE_CHECKS="+checks);}
}
